    image_patch = ImagePatch(image)
    rack_patches = image_patch.find("left rack")
    if not rack_patches: return image_patch
    ball_patches = image_patch.find("ball")
    if not ball_patches: return rack_patches[0]
    for rack in rack_patches:
        for ball in ball_patches:
            if rack.overlaps_with(rack.left, rack.lower, rack.right, rack.upper, ball.left, ball.lower, ball.right, ball.upper):
                return rack
    return rack_patches[0]

